import { useEffect, useRef } from 'react';
import { createPortal } from 'react-dom';
import { Icon } from '@/components/ui/Icon.js';
import { cx } from '@/lib/cx.js';
import type { MomentCopy } from './copy.js';
import styles from './MomentToast.module.css';

/** How long a moment's toast stays: long enough to read two short lines. */
const TOAST_MS = 5000;

/**
 * A moment at the foot of the screen, after the add sheet has closed (or on
 * Today): a words milestone. It leaves by itself and takes nothing away, so
 * it needs no button. Portalled, like every fixed overlay here. Said once
 * to a screen reader by its own status role.
 */
export function MomentToast({
  copy,
  onDone,
  wide = false,
}: {
  copy: MomentCopy;
  onDone: () => void;
  /** A round milestone said at toast size (250, 2,000, 5,000): a little more room. */
  wide?: boolean;
}): React.JSX.Element {
  const done = useRef(onDone);
  useEffect(() => {
    done.current = onDone;
  });
  useEffect(() => {
    const timer = window.setTimeout(() => {
      done.current();
    }, TOAST_MS);
    return () => {
      window.clearTimeout(timer);
    };
  }, []);
  return createPortal(
    <div className={cx(styles.toast, wide && styles.wide)} role="status" data-moment-toast="">
      <span className={styles.mark} aria-hidden="true">
        <Icon name={copy.icon === 'boxes' ? 'check' : copy.icon} size={18} weight={2.2} />
      </span>
      <span className={styles.text}>
        {copy.title !== undefined && <strong className={styles.title}>{copy.title}</strong>}
        <span className={styles.line}>{copy.line}</span>
      </span>
    </div>,
    document.body,
  );
}
